/**
 * Возвращает разные [SddsFinAiTypography] в зависимости от ширины окна. Значение динамически
 * изменяется при изменении ширины окна.
 */
@Composable
public fun dynamicSddsFinAiTypography(): SddsFinAiTypography {
    val widthClass = collectWindowSizeInfoAsState().value.widthClass
    return when (widthClass) {
        WindowSizeClass.Expanded -> largeSddsFinAiTypography()
        WindowSizeClass.Medium -> mediumSddsFinAiTypography()
        WindowSizeClass.Compact -> smallSddsFinAiTypography()
    }
}

